#if UNITY_EDITOR
using UnityEngine;
using UnityEditor;

/// <summary>
/// AAH_ModelReplacer — Editor tool to replace placeholder geometry with imported models.
/// Access via: Tools → AAH → Replace Placeholders With Models
/// 
/// This tool scans the scene for placeholder objects (Cubes, Spheres, Capsules)
/// that were generated by AAH_SceneBuilder and lets you swap them with real models.
/// </summary>
public class AAH_ModelReplacer : EditorWindow
{
    // Model references — drag your imported models here
    private GameObject hospitalModel;
    private GameObject receptionDeskModel;
    private GameObject examTableModel;
    private GameObject chairModel;
    private GameObject bedModel;
    
    private GameObject patient1Model;
    private GameObject patient2Model;
    private GameObject patient3Model;
    
    private GameObject drMuppleModel;
    
    private GameObject flashlightModel;

    private Vector2 scrollPos;

    [MenuItem("Tools/AAH/Replace Placeholders With Models")]
    public static void ShowWindow()
    {
        GetWindow<AAH_ModelReplacer>("AAH Model Replacer");
    }

    void OnGUI()
    {
        scrollPos = EditorGUILayout.BeginScrollView(scrollPos);

        GUILayout.Label("🏥 AAH Model Replacer", EditorStyles.boldLabel);
        GUILayout.Label("Drag your imported .glb models into the slots below,\nthen click the Replace buttons.", EditorStyles.helpBox);
        GUILayout.Space(10);

        // ─── ENVIRONMENT ─────────────────────────────────
        GUILayout.Label("── ENVIRONMENT ──", EditorStyles.boldLabel);
        
        hospitalModel = (GameObject)EditorGUILayout.ObjectField(
            "Hospital Building", hospitalModel, typeof(GameObject), false);
        if (hospitalModel != null && GUILayout.Button("▶ Replace Entire Hospital Layout"))
        {
            ReplaceEnvironment(hospitalModel);
        }

        GUILayout.Space(5);

        receptionDeskModel = (GameObject)EditorGUILayout.ObjectField(
            "Reception Desk", receptionDeskModel, typeof(GameObject), false);
        if (receptionDeskModel != null && GUILayout.Button("▶ Replace Reception Desk"))
        {
            ReplaceNamedObjects(new string[]{"ReceptionDesk_Top", "ReceptionDesk_Front", 
                "ReceptionDesk_Back", "ReceptionDesk_Left", "ReceptionDesk_Right"}, 
                receptionDeskModel, "ReceptionDesk", new Vector3(0, 0, 1f));
        }

        examTableModel = (GameObject)EditorGUILayout.ObjectField(
            "Exam Table", examTableModel, typeof(GameObject), false);
        if (examTableModel != null && GUILayout.Button("▶ Replace Exam Table"))
        {
            ReplaceNamedObjects(new string[]{"ExamTable_Top", "ExamTable_Leg1", 
                "ExamTable_Leg2", "ExamTable_Leg3", "ExamTable_Leg4"}, 
                examTableModel, "ExamTable", new Vector3(7f, 0, 10f));
        }

        chairModel = (GameObject)EditorGUILayout.ObjectField(
            "Chair", chairModel, typeof(GameObject), false);
        if (chairModel != null && GUILayout.Button("▶ Replace All Chairs"))
        {
            ReplaceChairs(chairModel);
        }

        bedModel = (GameObject)EditorGUILayout.ObjectField(
            "Hospital Bed", bedModel, typeof(GameObject), false);
        if (bedModel != null && GUILayout.Button("▶ Add Hospital Bed to Exam Room"))
        {
            AddModelToScene(bedModel, "HospitalBed", new Vector3(7f, 0, 12f),
                AAH_ModelSetup.ModelRole.Furniture_Bed);
        }

        GUILayout.Space(15);

        // ─── PATIENTS ────────────────────────────────────
        GUILayout.Label("── ANIMAL PATIENTS ──", EditorStyles.boldLabel);
        
        patient1Model = (GameObject)EditorGUILayout.ObjectField(
            "Patient 1 (Biscuit - Normal)", patient1Model, typeof(GameObject), false);
        if (patient1Model != null && GUILayout.Button("▶ Replace Patient Biscuit"))
        {
            ReplacePatient("Patient_Biscuit", patient1Model, "Biscuit the Rabbit", false);
        }

        patient2Model = (GameObject)EditorGUILayout.ObjectField(
            "Patient 2 (Spots - Normal)", patient2Model, typeof(GameObject), false);
        if (patient2Model != null && GUILayout.Button("▶ Replace Patient Spots"))
        {
            ReplacePatient("Patient_Spots", patient2Model, "Spots the Dalmatian", false);
        }

        patient3Model = (GameObject)EditorGUILayout.ObjectField(
            "Patient 3 (Rex - ANOMALY)", patient3Model, typeof(GameObject), false);
        if (patient3Model != null && GUILayout.Button("▶ Replace Patient Rex (Anomaly)"))
        {
            ReplacePatient("Patient_Anomaly_Rex", patient3Model, "Rex", true);
        }

        GUILayout.Space(15);

        // ─── NPCs ────────────────────────────────────────
        GUILayout.Label("── NPCs ──", EditorStyles.boldLabel);
        
        drMuppleModel = (GameObject)EditorGUILayout.ObjectField(
            "Dr. Mupple", drMuppleModel, typeof(GameObject), false);
        if (drMuppleModel != null && GUILayout.Button("▶ Add Dr. Mupple to Scene"))
        {
            AddModelToScene(drMuppleModel, "NPC_DrMupple", new Vector3(2f, 0, -4f),
                AAH_ModelSetup.ModelRole.NPC_DrMupple);
        }

        GUILayout.Space(15);

        // ─── EQUIPMENT ───────────────────────────────────
        GUILayout.Label("── EQUIPMENT ──", EditorStyles.boldLabel);
        
        flashlightModel = (GameObject)EditorGUILayout.ObjectField(
            "Flashlight", flashlightModel, typeof(GameObject), false);
        if (flashlightModel != null && GUILayout.Button("▶ Replace Player Flashlight"))
        {
            ReplaceFlashlight(flashlightModel);
        }

        GUILayout.Space(20);

        // ─── QUICK ACTIONS ───────────────────────────────
        GUILayout.Label("── QUICK ACTIONS ──", EditorStyles.boldLabel);
        
        if (GUILayout.Button("🔄 Remove All Placeholder Geometry"))
        {
            if (EditorUtility.DisplayDialog("Remove Placeholders",
                "This will delete all primitive Cube/Sphere geometry\n" +
                "from the ENVIRONMENT group.\n\nAre you sure?", "Yes", "Cancel"))
            {
                RemoveAllPlaceholders();
            }
        }

        if (GUILayout.Button("💾 Save Scene"))
        {
            UnityEditor.SceneManagement.EditorSceneManager.SaveOpenScenes();
            Debug.Log("[AAH] Scene saved.");
        }

        EditorGUILayout.EndScrollView();
    }

    // ─── REPLACEMENT LOGIC ────────────────────────────────────────

    void ReplaceEnvironment(GameObject model)
    {
        // Find the ENVIRONMENT group
        GameObject envGroup = GameObject.Find("=== ENVIRONMENT ===");
        if (envGroup == null)
        {
            Debug.LogError("[AAH] Cannot find '=== ENVIRONMENT ===' in scene!");
            return;
        }

        // Deactivate all placeholder children but keep the parent
        foreach (Transform child in envGroup.transform)
        {
            child.gameObject.SetActive(false);
        }

        // Instantiate hospital model
        GameObject instance = (GameObject)PrefabUtility.InstantiatePrefab(model);
        if (instance == null)
            instance = Instantiate(model);
            
        instance.name = "Hospital_Environment";
        instance.transform.SetParent(envGroup.transform);
        instance.transform.position = Vector3.zero;
        instance.transform.rotation = Quaternion.identity;

        // Setup
        AAH_ModelSetup setup = instance.AddComponent<AAH_ModelSetup>();
        setup.role = AAH_ModelSetup.ModelRole.Environment_HospitalBuilding;
        setup.AutoSetup();

        Debug.Log("[AAH] ✅ Hospital environment model placed. Adjust position/rotation/scale in Inspector.");
        EditorUtility.DisplayDialog("Environment Replaced",
            "Hospital model placed!\n\n" +
            "Now adjust:\n" +
            "1. Position/Rotation/Scale to fit the scene\n" +
            "2. Move Player spawn point if needed\n" +
            "3. Move Patient positions to match rooms", "OK");
    }

    void ReplaceNamedObjects(string[] namesToRemove, GameObject newModel, string newName, Vector3 position)
    {
        // Remove old placeholder pieces
        foreach (string name in namesToRemove)
        {
            GameObject old = FindInScene(name);
            if (old != null) DestroyImmediate(old);
        }

        // Add new model
        AddModelToScene(newModel, newName, position, AAH_ModelSetup.ModelRole.Prop_Generic);
    }

    void ReplaceChairs(GameObject model)
    {
        string[] chairNames = { "Chair_1", "Chair_2", "Chair_3" };
        Vector3[] positions = {
            new Vector3(-6f, 0, 1f),
            new Vector3(-7f, 0, 1f),
            new Vector3(-8f, 0, 1f)
        };

        for (int i = 0; i < chairNames.Length; i++)
        {
            GameObject old = FindInScene(chairNames[i]);
            if (old != null) DestroyImmediate(old);

            AddModelToScene(model, $"Chair_{i+1}", positions[i],
                AAH_ModelSetup.ModelRole.Furniture_Chair);
        }
    }

    void ReplacePatient(string oldName, GameObject newModel, string patientName, bool isAnomaly)
    {
        // Find old patient
        GameObject old = FindInScene(oldName);
        Transform parent = null;
        Vector3 pos = Vector3.zero;
        bool wasActive = true;

        if (old != null)
        {
            parent = old.transform.parent;
            pos = old.transform.position;
            wasActive = old.activeSelf;
            DestroyImmediate(old);
        }
        else
        {
            // Default positions
            parent = GameObject.Find("=== PATIENTS ===")?.transform;
        }

        // Instantiate new model
        GameObject instance = (GameObject)PrefabUtility.InstantiatePrefab(newModel);
        if (instance == null)
            instance = Instantiate(newModel);
            
        instance.name = isAnomaly ? $"Patient_Anomaly_{patientName}" : $"Patient_{patientName}";
        if (parent != null) instance.transform.SetParent(parent);
        instance.transform.position = pos;

        // Setup as patient
        AAH_ModelSetup setup = instance.AddComponent<AAH_ModelSetup>();
        setup.role = isAnomaly ? AAH_ModelSetup.ModelRole.Patient_Anomaly : AAH_ModelSetup.ModelRole.Patient_Normal;
        setup.patientName = patientName;
        setup.AutoSetup();

        instance.SetActive(wasActive);

        // Re-wire reception desk
        RewireReceptionDesk();

        Debug.Log($"[AAH] ✅ Patient '{patientName}' replaced with new model.");
    }

    void ReplaceFlashlight(GameObject model)
    {
        // Find existing flashlight on player camera
        GameObject playerCam = GameObject.FindGameObjectWithTag("MainCamera");
        if (playerCam == null)
        {
            Debug.LogError("[AAH] Cannot find MainCamera!");
            return;
        }

        Transform oldFlashlight = playerCam.transform.Find("Flashlight");
        Vector3 localPos = new Vector3(0.3f, -0.2f, 0.5f);
        if (oldFlashlight != null)
        {
            localPos = oldFlashlight.localPosition;
            DestroyImmediate(oldFlashlight.gameObject);
        }

        GameObject instance = (GameObject)PrefabUtility.InstantiatePrefab(model);
        if (instance == null) instance = Instantiate(model);
        
        instance.name = "Flashlight";
        instance.transform.SetParent(playerCam.transform);
        instance.transform.localPosition = localPos;
        instance.transform.localRotation = Quaternion.identity;
        instance.transform.localScale = Vector3.one * 0.1f;

        // Add light if none
        if (instance.GetComponentInChildren<Light>() == null)
        {
            Light fl = instance.AddComponent<Light>();
            fl.type = LightType.Spot;
            fl.spotAngle = 45f;
            fl.intensity = 2f;
            fl.range = 12f;
            fl.color = new Color(1f, 0.97f, 0.9f);
        }
    }

    void AddModelToScene(GameObject model, string name, Vector3 position, AAH_ModelSetup.ModelRole role)
    {
        GameObject instance = (GameObject)PrefabUtility.InstantiatePrefab(model);
        if (instance == null) instance = Instantiate(model);
        
        instance.name = name;
        instance.transform.position = position;

        AAH_ModelSetup setup = instance.AddComponent<AAH_ModelSetup>();
        setup.role = role;
        setup.AutoSetup();
    }

    void RewireReceptionDesk()
    {
        AAH_ReceptionDesk desk = Object.FindFirstObjectByType<AAH_ReceptionDesk>();
        if (desk == null) return;

        Transform patientsRoot = null;
        foreach (Transform t in Object.FindObjectsByType<Transform>(FindObjectsSortMode.None))
        {
            if (t.name == "=== PATIENTS ===")
            {
                patientsRoot = t;
                break;
            }
        }

        if (patientsRoot != null && patientsRoot.childCount > 0)
        {
            desk.patientObjects = new GameObject[patientsRoot.childCount];
            for (int i = 0; i < patientsRoot.childCount; i++)
                desk.patientObjects[i] = patientsRoot.GetChild(i).gameObject;
            
            EditorUtility.SetDirty(desk);
        }
    }

    void RemoveAllPlaceholders()
    {
        GameObject env = GameObject.Find("=== ENVIRONMENT ===");
        if (env == null) return;

        int count = 0;
        for (int i = env.transform.childCount - 1; i >= 0; i--)
        {
            Transform child = env.transform.GetChild(i);
            if (child.GetComponent<MeshFilter>() != null)
            {
                MeshFilter mf = child.GetComponent<MeshFilter>();
                if (mf.sharedMesh != null && 
                    (mf.sharedMesh.name == "Cube" || mf.sharedMesh.name == "Sphere" || mf.sharedMesh.name == "Capsule"))
                {
                    DestroyImmediate(child.gameObject);
                    count++;
                }
            }
        }
        Debug.Log($"[AAH] Removed {count} placeholder objects.");
    }

    GameObject FindInScene(string name)
    {
        // Deep search
        foreach (var go in Object.FindObjectsByType<Transform>(FindObjectsSortMode.None))
        {
            if (go.name == name) return go.gameObject;
        }
        return null;
    }
}
#endif
